<script setup lang="ts">
import config from '../../app-definition.json';
const values=reactive<Record<string,string>>({});
const pending=ref(false);const message=ref('');const failed=ref(false);
useHead({title:config.title,meta:[{name:'description',content:config.description}],link:[{rel:'stylesheet',href:'/style.css'},{rel:'icon',href:'/favicon.svg'}]});
async function submit(){pending.value=true;message.value='';try{const result=await $fetch<{ok:boolean;message:string}>('/api/submit',{method:'POST',body:values,headers:{Accept:'application/json'}});message.value=result.message;failed.value=!result.ok;if(result.ok)for(const key in values)values[key]=''}catch(error:any){message.value=error.data?.message || 'Your request could not be saved. Please try again.';failed.value=true}finally{pending.value=false}}
</script>
<template><header class="site-header"><a class="wordmark" href="/">{{config.title}}</a><a class="quiet-link" href="/admin">Operator</a></header><main><section class="hero"><div><div class="eyebrow">{{config.eyebrow}}</div><h1>{{config.headline}}</h1><p class="intro">{{config.description}}</p></div><form class="card" method="post" action="/api/submit" @submit.prevent="submit"><h2>{{config.button}}</h2><div v-if="message" :role="failed?'alert':'status'" :class="['notice',{error:failed}]">{{message}}</div><label v-for="field in config.fields" :key="field.name"><span>{{field.label}}</span><textarea v-if="field.type==='textarea'" v-model="values[field.name]" :name="field.name" rows="4" maxlength="2000" required></textarea><select v-else-if="field.options" v-model="values[field.name]" :name="field.name" required><option value="">Choose an option</option><option v-for="option in field.options" :key="option.value" :value="option.value">{{option.label}}</option></select><input v-else v-model="values[field.name]" :type="field.type" :name="field.name" maxlength="300" required/></label><button :disabled="pending">{{pending?'Saving…':config.button}}</button><p class="form-note">{{config.formNote}}</p></form></section></main><footer>Small tools, useful work. <span>Nuxt</span></footer></template>
